one=np.ones_like(P)
def fit2(w,cols):
    s=np.sin(w*t); c=np.cos(w*t)
    d={'1':one,'t':t,'t2':t**2,'s':s,'c':c,'P':P,'Ps':P*s,'Pc':P*c,'Pt':P*t,'P2':P**2,'P3':P**3,'P3s':P**3*s,'P3c':P**3*c,'P2s':P**2*s,'P2c':P**2*c,'ts':t*s,'tc':t*c,'Pt2':P*t**2}
    X=np.array([d[k] for k in cols]).T
    b=np.linalg.lstsq(X,y,rcond=None)[0]
    return np.mean((y-X@b)**2)/np.var(y), dict(zip(cols,np.round(b,4)))
